'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Float64Array = require( '@stdlib/array/float64' );
var Uint8Array = require( '@stdlib/array/uint8' );
var abs = require( '@stdlib/math/base/special/abs' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dpbequ = require( './../lib' );


// FUNCTIONS //

/**
* Creates bounded scaling benchmarks with complete output/input checks.
*
* @private
* @param {PositiveInteger} N - matrix order
* @param {boolean} upper - whether to use upper storage
* @param {boolean} failed - whether the second diagonal is negative zero
* @returns {Function} benchmark function
*/
function createBenchmark( N, upper, failed ) {
	var before;
	var bytes;
	var SCOND;
	var AMAX;
	var AB;
	var ss;
	var os;
	var S;
	var r;
	var c;
	var o;
	var j;

	AB = new Float64Array( 2*N );
	S = new Float64Array( N+2 );
	SCOND = new Float64Array( 1 );
	AMAX = new Float64Array( 1 );
	r = 1;
	c = -2;
	o = 2*(N-1);
	ss = -1;
	os = N;
	for ( j = 0; j < AB.length; j++ ) {
		AB[ j ] = NaN;
	}
	for ( j = 0; j < N; j++ ) {
		AB[ o+(( ( upper ) ? 1 : 0 )*r)+(j*c) ] = ( failed && j === 1 ) ? -0.0 : (j+2)*(j+2);
	}
	bytes = new Uint8Array( AB.buffer );
	before = new Uint8Array( bytes );
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var diagonal;
		var index;
		var info;
		var i;
		var j;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			// Output reset is included in the measured workload:
			for ( j = 0; j < S.length; j++ ) {
				S[ j ] = 7.0;
			}
			SCOND[ 0 ] = -0.0;
			AMAX[ 0 ] = -9.0;
			info = dpbequ.ndarray( ( upper ) ? 'upper' : 'lower', N, 1, AB, r, c, o, S, ss, os, SCOND, 0, AMAX, 0 );
			if ( info !== (( failed ) ? 2 : 0) ) {
				b.fail( 'should return the expected scaling status' );
				b.end();
				return;
			}
		}
		b.toc();
		for ( j = 0; j < N; j++ ) {
			index = os+(j*ss);
			diagonal = AB[ o+(( ( upper ) ? 1 : 0 )*r)+(j*c) ];
			if ( failed ) {
				if ( S[ index ] !== diagonal || (j === 1 && 1/S[ index ] !== -Infinity) ) {
					b.fail( 'should copy every failure diagonal and preserve zero sign' );
					b.end();
					return;
				}
			} else if ( !( abs( (S[ index ]*S[ index ]*diagonal)-1.0 ) <= 1.0e-14 ) ) {
				b.fail( 'should scale each positive diagonal to one' );
				b.end();
				return;
			}
		}
		if ( AMAX[ 0 ] !== (N+1)*(N+1) || (( failed ) ? 1/SCOND[ 0 ] !== -Infinity : SCOND[ 0 ] !== 2/(N+1)) ) {
			b.fail( 'should check full AMAX and SCOND output/sentinel' );
			b.end();
			return;
		}
		for ( j = 0; j < bytes.length; j++ ) {
			if ( bytes[ j ] !== before[ j ] ) {
				b.fail( 'should preserve every input byte' );
				b.end();
				return;
			}
		}
		for ( j = 0; j < S.length; j++ ) {
			if ( ((j < os+((N-1)*ss) || j > os) && ss < 0) || ((j < os || j > os+((N-1)*ss)) && ss > 0) ) {
				if ( S[ j ] !== 7.0 ) {
					b.fail( 'should retain unused output guards' );
					b.end();
					return;
				}
			}
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var options;
	var sizes;
	var name;
	var fcn;
	var i;
	var j;
	var k;

	options = {
		'iterations': 200,
		'repeats': 2
	};
	sizes = [ 8, 16 ];
	for ( i = 0; i < sizes.length; i++ ) {
		for ( j = 0; j < 2; j++ ) {
			for ( k = 0; k < 2; k++ ) {
				name = format( '%s:N=%d:upper=%d:failed=%d', pkg, sizes[ i ], j, k );
				fcn = createBenchmark( sizes[ i ], j === 1, k === 1 );
				bench( name, options, fcn );
			}
		}
	}
}

main();
